<?php
/**  * Merchandise Stock-In API  * Called by staff_stock_in.php when staff encodes actual received items.  * This is the ONLY endpoint that updates inventory stock levels.  *  * Actions:  *  submit_stock_in  — POST: encode received items, update inventory, mark PO done  *  get_history  — GET:  fetch stock-in history for a station  */
require_once '../lib.php';
require_once '../../public/db_connect.php';  header('Content-Type: application/json');  $me = current_user();
if (!$me) {  echo json_encode(['success' => false, 'message' => 'Not authenticated']);  exit;
}  $role  = role_key($me['role'] ?? 'staff');
$station_id = (int)user_station_id();
$action  = $_GET['action'] ?? '';
$method  = $_SERVER['REQUEST_METHOD'];  // Only staff, admin, superadmin can encode stock-in
if (!in_array($role, ['staff', 'cashier', 'pump_attendant', 'admin', 'superadmin'])) {  echo json_encode(['success' => false, 'message' => 'Access denied']);  exit;
}  // Ensure merchandise_stock_in table exists
try {  $pdo->exec("CREATE TABLE IF NOT EXISTS merchandise_stock_in (  id  INT AUTO_INCREMENT PRIMARY KEY,  po_id  INT NULL,  po_number  VARCHAR(100) NULL,  station_id  INT NOT NULL,  product_id  INT NOT NULL,  product_name  VARCHAR(255) NOT NULL,  sku  VARCHAR(100) NULL,  category  VARCHAR(100) NULL,  qty_ordered  INT NOT NULL DEFAULT 0,  qty_received  INT NOT NULL DEFAULT 0,  qty_variance  INT NOT NULL DEFAULT 0,  unit_cost  DECIMAL(10,2) NOT NULL DEFAULT 0,  total_cost  DECIMAL(12,2) NOT NULL DEFAULT 0,  condition_flag ENUM('Good','Damaged','Short','Excess') NOT NULL DEFAULT 'Good',  remarks  TEXT NULL,  stock_before  INT NOT NULL DEFAULT 0,  stock_after  INT NOT NULL DEFAULT 0,  encoded_by  INT NOT NULL,  encoded_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,  batch_ref  VARCHAR(100) NULL,  INDEX idx_station  (station_id),  INDEX idx_encoded_at (encoded_at),  INDEX idx_po_id  (po_id)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
} catch (Exception $e) {}  // Ensure merchandise_batches table exists
try {  $pdo->exec("CREATE TABLE IF NOT EXISTS merchandise_batches (  id  INT AUTO_INCREMENT PRIMARY KEY,  product_id  INT  NOT NULL,  station_id  INT  NOT NULL,  batch_number  VARCHAR(50)  NOT NULL,  delivery_id  INT  DEFAULT NULL,  quantity_received INT  NOT NULL DEFAULT 0,  remaining_qty  INT  NOT NULL DEFAULT 0,  unit_cost  DECIMAL(12,4) NOT NULL DEFAULT 0,  supplier  VARCHAR(200) DEFAULT NULL,  date_received  DATE  NOT NULL,  encoded_by  INT  DEFAULT NULL,  validated_by  INT  DEFAULT NULL,  validated_at  DATETIME  DEFAULT NULL,  status  ENUM('active','depleted','cancelled') NOT NULL DEFAULT 'active',  notes  TEXT  DEFAULT NULL,  created_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,  updated_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,  INDEX idx_product (product_id),  INDEX idx_station (station_id)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
} catch (Exception $e) {}  // Ensure fuel_stock_in table exists
try {  $pdo->exec("CREATE TABLE IF NOT EXISTS fuel_stock_in (  id  INT AUTO_INCREMENT PRIMARY KEY,  delivery_id  INT NOT NULL,  invoice_no  VARCHAR(100) NULL,  station_id  INT NOT NULL,  fuel_type  VARCHAR(255) NOT NULL,  qty_expected  DECIMAL(12,2) NOT NULL DEFAULT 0,  qty_received  DECIMAL(12,2) NOT NULL DEFAULT 0,  qty_variance  DECIMAL(12,2) NOT NULL DEFAULT 0,  condition_flag ENUM('Good','Damaged','Short','Excess') NOT NULL DEFAULT 'Good',  remarks  TEXT NULL,  level_before  DECIMAL(12,2) NOT NULL DEFAULT 0,  level_after  DECIMAL(12,2) NOT NULL DEFAULT 0,  encoded_by  INT NOT NULL,  encoded_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,  batch_ref  VARCHAR(100) NULL,  delivery_ref  VARCHAR(100) NULL,  INDEX idx_station (station_id),  INDEX idx_encoded_at (encoded_at),  INDEX idx_delivery_id (delivery_id)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");  // Add delivery_ref column if not exists (migration)  $pdo->exec("ALTER TABLE fuel_stock_in ADD COLUMN IF NOT EXISTS delivery_ref VARCHAR(100) NULL");
} catch (Exception $e) {}  // Bootstrap fuel_batches table — mirrors merchandise_batches but for fuel
try {  $pdo->exec("  CREATE TABLE IF NOT EXISTS fuel_batches (  id  INT AUTO_INCREMENT PRIMARY KEY,  fuel_type_id  INT  NOT NULL,  station_id  INT  NOT NULL,  batch_number  VARCHAR(50)  NOT NULL,  delivery_id  INT  DEFAULT NULL COMMENT 'fuel_deliveries.id',  quantity_received DECIMAL(12,2) NOT NULL DEFAULT 0,  remaining_qty  DECIMAL(12,2) NOT NULL DEFAULT 0,  unit_cost  DECIMAL(12,4) NOT NULL DEFAULT 0,  supplier  VARCHAR(200) DEFAULT NULL,  date_received  DATE  NOT NULL,  encoded_by  INT  DEFAULT NULL,  status  ENUM('active','depleted','cancelled') NOT NULL DEFAULT 'active',  notes  TEXT  DEFAULT NULL,  created_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,  updated_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,  INDEX idx_fuel_type  (fuel_type_id),  INDEX idx_station  (station_id),  INDEX idx_status  (status),  INDEX idx_date  (date_received)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ");
} catch (Exception $e) {  error_log('fuel_batches bootstrap: ' . $e->getMessage());
}  // Ensure purchase_orders has required columns
foreach ([  "ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS admin_finalized TINYINT(1) NOT NULL DEFAULT 0",  "ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS stock_in_done  TINYINT(1) NOT NULL DEFAULT 0",  "ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS stock_in_at  DATETIME NULL",  "ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS stock_in_by  INT NULL",
] as $sql) { try { $pdo->exec($sql); } catch (Exception $e) {} }  // Ensure stock_requests table has updated_at column (defensive schema check)
try {  $pdo->exec("ALTER TABLE stock_requests ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP");
} catch (Exception $e) {  // Column may already exist or table may not exist yet  error_log("stock_requests updated_at column check: " . $e->getMessage());
}  try {  switch ($action) {  case 'submit_stock_in':  if ($method !== 'POST') {  echo json_encode(['success' => false, 'message' => 'POST required']);  exit;  }  handle_submit_stock_in($pdo, $me, $role, $station_id);  break;  case 'submit_fuel_stock_in':  if ($method !== 'POST') {  echo json_encode(['success' => false, 'message' => 'POST required']);  exit;  }  handle_submit_fuel_stock_in($pdo, $me, $role, $station_id);  break;  case 'get_history':  handle_get_history($pdo, $station_id);  break;  default:  echo json_encode(['success' => false, 'message' => 'Invalid action']);  }
} catch (Exception $e) {  error_log("Merchandise Stock-In API Error: " . $e->getMessage());  echo json_encode(['success' => false, 'message' => 'Server error: ' . $e->getMessage()]);
}  // ─────────────────────────────────────────────────────────────────────────────
// HANDLERS
// ─────────────────────────────────────────────────────────────────────────────  function handle_submit_stock_in($pdo, $me, $role, $station_id) {  $input = json_decode(file_get_contents('php://input'), true);  if (!$input) {  echo json_encode(['success' => false, 'message' => 'Invalid JSON input']);  return;  }  $delivery_id = (int)($input['delivery_id'] ?? 0);  // NEW: from deliveries_oversight  $po_id  = (int)($input['po_id']  ?? 0);  // LEGACY: fallback for old flow  $items  = $input['items']  ?? [];  $batch_note  = trim($input['batch_note']  ?? '');  $batch_id  = trim($input['batch_id']  ?? '');  // Staff-entered or delivery batch_id  // Prioritize delivery_id (new flow from Admin processing)  if ($delivery_id > 0) {  // NEW FLOW: Fetch from deliveries_oversight  $stmt = $pdo->prepare("  SELECT  do2.id AS delivery_id,  do2.delivery_ref AS po_number,  do2.supplier,  do2.product AS product_name,  do2.quantity,  do2.expected_quantity,  do2.actual_quantity,  do2.unit_price,  do2.batch_id AS delivery_batch_id,  ip.id AS product_id,  ip.sku,  ip.category  FROM deliveries_oversight do2  LEFT JOIN inventory_products ip  ON ip.product_name = do2.product AND ip.category != 'Fuel'  WHERE do2.id = ? AND do2.station_id = ?  AND do2.delivery_type = 'merchandise'  AND do2.status IN ('Ready for Stock-In', 'Validated', 'Partial Delivery', 'Damaged Items')  ");  $stmt->execute([$delivery_id, $station_id]);  $po = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$po) {  echo json_encode(['success' => false, 'message' => 'Delivery not found, not yet validated by Admin, or already stocked in']);  return;  }  // Map delivery data to legacy PO structure for compatibility  $po['id'] = $delivery_id;  $po['quantity'] = (float)$po['actual_quantity'] ?: $po['quantity'];  $po['supplier_name'] = $po['supplier'];  if (!$batch_id && !empty($po['delivery_batch_id'])) {  $batch_id = $po['delivery_batch_id'];  }  } elseif ($po_id > 0) {  // LEGACY FLOW: Fetch from purchase_orders (for backwards compatibility)  $stmt = $pdo->prepare("  SELECT po.*, ip.id AS product_id, ip.sku, ip.category  FROM purchase_orders po  LEFT JOIN inventory_products ip  ON ip.product_name = po.product_name AND ip.category != 'Fuel'  WHERE po.id = ? AND po.station_id = ?  AND po.type = 'merch'  AND po.admin_finalized  = 1  AND po.delivery_validated = 1  AND po.stock_in_done  = 0  ");  $stmt->execute([$po_id, $station_id]);  $po = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$po) {  echo json_encode(['success' => false, 'message' => 'PO not found, already stocked in, not yet finalized by Admin, or not yet validated by Manager']);  return;  }  } else {  echo json_encode(['success' => false, 'message' => 'Delivery ID or PO ID is required']);  return;  }  if (empty($items)) {  echo json_encode(['success' => false, 'message' => 'No items provided']);  return;  }  $product_id = (int)($po['product_id'] ?? 0);  if ($product_id <= 0) {  // Try to find product by name  $ps = $pdo->prepare("SELECT id FROM inventory_products WHERE product_name = ? AND category != 'Fuel' LIMIT 1");  $ps->execute([$po['product_name']]);  $product_id = (int)($ps->fetchColumn() ?: 0);  }  if ($product_id <= 0) {  echo json_encode(['success' => false, 'message' => 'Product not found in inventory_products. Cannot update stock.']);  return;  }  // Use staff-entered batch_id, fall back to PO batch_id, then auto-generate  $effective_batch_id = $batch_id ?: ($po['batch_id'] ?? '');  if (empty($effective_batch_id)) {  $effective_batch_id = 'B-' . date('Ymd') . '-PO' . str_pad($po_id, 4, '0', STR_PAD_LEFT);  }  $batch_ref = 'SI-' . date('Ymd-His') . '-PO' . str_pad($po_id, 4, '0', STR_PAD_LEFT);  $pdo->beginTransaction();  try {  $total_received = 0;  $si_records  = [];  foreach ($items as $item) {  $item_product_id = (int)($item['product_id'] ?? $product_id);  $qty_received  = (int)($item['qty_received']  ?? 0);  $qty_ordered  = (int)($item['qty_ordered']  ?? $po['quantity']);  $unit_cost  = (float)($item['unit_cost']  ?? $po['unit_price'] ?? 0);  $condition  = $item['condition']  ?? 'Good';  $remarks  = trim($item['remarks']  ?? '');  if (!in_array($condition, ['Good', 'Damaged', 'Short', 'Excess'])) {  $condition = 'Good';  }  // Get current stock level  $stock_before = 0;  $si_row = $pdo->prepare("SELECT stock_level FROM station_inventory WHERE product_id = ? AND station_id = ?");  $si_row->execute([$item_product_id, $station_id]);  $si_data = $si_row->fetch(PDO::FETCH_ASSOC);  if ($si_data) {  $stock_before = (int)$si_data['stock_level'];  } else {  // Fallback: check inventory_products.stock  $ip_row = $pdo->prepare("SELECT COALESCE(stock, 0) AS stock FROM inventory_products WHERE id = ?");  $ip_row->execute([$item_product_id]);  $stock_before = (int)($ip_row->fetchColumn() ?: 0);  }  // Only add to inventory if condition is Good or Excess  $qty_to_add = 0;  if (in_array($condition, ['Good', 'Excess'])) {  $qty_to_add = $qty_received;  }  // Short/Damaged: do NOT add to inventory (flag only)  $stock_after  = $stock_before + $qty_to_add;  $qty_variance = $qty_received - $qty_ordered;  $total_cost  = round($unit_cost * $qty_received, 2);  // Update station_inventory  if ($qty_to_add > 0) {  $check = $pdo->prepare("SELECT id FROM station_inventory WHERE product_id = ? AND station_id = ?");  $check->execute([$item_product_id, $station_id]);  if ($check->fetch()) {  $pdo->prepare("  UPDATE station_inventory  SET stock_level = stock_level + ?,  last_updated  = NOW()  WHERE product_id = ? AND station_id = ?  ")->execute([$qty_to_add, $item_product_id, $station_id]);  } else {  $pdo->prepare("  INSERT INTO station_inventory (product_id, station_id, stock_level, status, last_updated)  VALUES (?, ?, ?, 'active', NOW())  ")->execute([$item_product_id, $station_id, $qty_to_add]);  }  // Log to inventory_logs  try {  $log_notes = "Stock-In Delivery - Batch: " . $effective_batch_id . " | PO Ref: " . ($po['po_number'] ?? '');  if ($remarks) $log_notes .= " | Notes: " . $remarks;  $pdo->prepare("  INSERT INTO inventory_logs (  station_id, product_id, user_id, action,  quantity_before, quantity_after, quantity_change,  reference_type, reference_id, notes, created_at  ) VALUES (?, ?, ?, 'delivery', ?, ?, ?, 'stock_in', ?, ?, NOW())  ")->execute([  $station_id,  $item_product_id,  $me['id'],  $stock_before,  $stock_after,  $qty_to_add,  $delivery_id ?: $po_id,  $log_notes  ]);  } catch (Exception $logErr) {  error_log("Inventory log insert error in Stock-In: " . $logErr->getMessage());  }  // Also update inventory_products.stock as fallback  try {  $pdo->prepare("UPDATE inventory_products SET stock = stock + ? WHERE id = ?")  ->execute([$qty_to_add, $item_product_id]);  } catch (Exception $e) {}  }  // Record stock-in entry  $pdo->prepare("  INSERT INTO merchandise_stock_in  (po_id, po_number, station_id, product_id, product_name, sku, category,  qty_ordered, qty_received, qty_variance, unit_cost, total_cost,  condition_flag, remarks, stock_before, stock_after,  encoded_by, encoded_at, batch_ref)  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)  ")->execute([  $po_id,  $po['po_number'] ?? '',  $station_id,  $item_product_id,  $po['product_name'],  $po['sku'] ?? '',  $po['category'] ?? '',  $qty_ordered,  $qty_received,  $qty_variance,  $unit_cost,  $total_cost,  $condition,  $remarks,  $stock_before,  $stock_after,  $me['id'],  $batch_ref  ]);  // ── AUTO-CREATE MERCHANDISE BATCH RECORD (FIFO) ──────────────────  // Only create a batch for Good/Excess deliveries that increase stock  if ($qty_to_add > 0) {  try {  // Check if this exact batch_number already exists for this product/station  $batchCheck = $pdo->prepare("SELECT id FROM merchandise_batches WHERE product_id = ? AND station_id = ? AND batch_number = ? LIMIT 1");  $batchCheck->execute([$item_product_id, $station_id, $effective_batch_id]);  if (!$batchCheck->fetch()) {  $delivery_ref_id = $delivery_id > 0 ? $delivery_id : $po_id;  $pdo->prepare("  INSERT INTO merchandise_batches  (product_id, station_id, batch_number, delivery_id, quantity_received,  remaining_qty, unit_cost, supplier, date_received, encoded_by, status,  notes, created_at, updated_at)  VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURDATE(), ?, 'active', ?, NOW(), NOW())  ")->execute([  $item_product_id,  $station_id,  $effective_batch_id,  $delivery_ref_id,  // delivery_id for traceability  $qty_received,  $qty_to_add,  // remaining = qty added to stock  $unit_cost,  $po['supplier_name'] ?? $po['supplier'] ?? '',  $me['id'],  ($remarks ?: ('Stock-In from ' . ($po['po_number'] ?? 'Delivery')))  ]);  } else {  // Batch already exists — update remaining_qty (cumulative delivery)  $pdo->prepare("  UPDATE merchandise_batches  SET remaining_qty = remaining_qty + ?,  quantity_received = quantity_received + ?,  updated_at = NOW()  WHERE product_id = ? AND station_id = ? AND batch_number = ?  ")->execute([$qty_to_add, $qty_received, $item_product_id, $station_id, $effective_batch_id]);  }  } catch (Exception $be) {  // Non-fatal: batch table error should not fail the whole stock-in  error_log("merchandise_batches insert error: " . $be->getMessage());  }  }  $total_received += $qty_received;  $si_records[] = [  'product'  => $po['product_name'],  'qty_received' => $qty_received,  'condition'  => $condition,  'stock_before' => $stock_before,  'stock_after'  => $stock_after,  'batch_id'  => $effective_batch_id,  ];  }  // Mark delivery as stocked in  if ($delivery_id > 0) {  // NEW FLOW: Update deliveries_oversight  $pdo->prepare("  UPDATE deliveries_oversight  SET status = 'Stock-In Complete',  updated_at = NOW()  WHERE id = ?  ")->execute([$delivery_id]);  } elseif ($po_id > 0) {  // LEGACY FLOW: Update purchase_orders  $pdo->prepare("  UPDATE purchase_orders  SET stock_in_done = 1,  stock_in_at  = NOW(),  stock_in_by  = ?,  status  = 'Stock-In Complete',  updated_at  = NOW()  WHERE id = ?  ")->execute([$me['id'], $po_id]);  // Update stock_requests status to 'Received' if linked  if (!empty($po['request_id'])) {  try {  $pdo->prepare("UPDATE stock_requests SET status = 'Received' WHERE id = ?")  ->execute([$po['request_id']]);  } catch (Exception $e) {}  }  }  // Audit log  $ref_number = $delivery_id > 0 ? "Delivery #{$delivery_id}" : "PO: {$po['po_number']}";  $detail = "Stock-In | {$ref_number} | Product: {$po['product_name']} | Received: {$total_received} | Batch: {$effective_batch_id} | Ref: {$batch_ref}";  if ($batch_note) $detail .= " | Note: {$batch_note}";  try {  $entity_id = $delivery_id > 0 ? $delivery_id : $po_id;  $entity_type = $delivery_id > 0 ? 'deliveries_oversight' : 'purchase_orders';  $pdo->prepare("  INSERT INTO audit_logs  (user_id, log_type, action_type, action_details, entity_type, entity_id, status, ip_address, user_agent, created_at)  VALUES (?, 'inventory', 'Stock-In', ?, ?, ?, 'Success', ?, ?, NOW())  ")->execute([  $me['id'], $detail, $entity_type, $entity_id,  $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0',  $_SERVER['HTTP_USER_AGENT'] ?? ''  ]);  } catch (Exception $e) {}  if (function_exists('log_activity')) {  log_activity($pdo, $me['id'], 'Merchandise Stock-In', $detail);  }  $pdo->commit();  echo json_encode([  'success'  => true,  'message'  => "Stock-In complete. Inventory updated for {$po['product_name']}.",  'batch_ref'  => $batch_ref,  'batch_id'  => $effective_batch_id,  'records'  => $si_records,  ]);  } catch (Exception $e) {  $pdo->rollBack();  throw $e;  }
}  function handle_get_history($pdo, $station_id) {  $date_from = $_GET['date_from'] ?? date('Y-m-d', strtotime('-30 days'));  $date_to  = $_GET['date_to']  ?? date('Y-m-d');  $per_page  = max(1, min(100, (int)($_GET['per_page'] ?? 50)));  $page  = max(1, (int)($_GET['page'] ?? 1));  $offset  = ($page - 1) * $per_page;  $stmt = $pdo->prepare("  SELECT msi.*, u.name AS encoded_by_name  FROM merchandise_stock_in msi  LEFT JOIN users u ON msi.encoded_by = u.id  WHERE msi.station_id = ?  AND DATE(msi.encoded_at) BETWEEN ? AND ?  ORDER BY msi.encoded_at DESC  LIMIT $per_page OFFSET $offset  ");  $stmt->execute([$station_id, $date_from, $date_to]);  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  $cnt = $pdo->prepare("  SELECT COUNT(*) FROM merchandise_stock_in  WHERE station_id = ? AND DATE(encoded_at) BETWEEN ? AND ?  ");  $cnt->execute([$station_id, $date_from, $date_to]);  $total = (int)$cnt->fetchColumn();  echo json_encode([  'success'  => true,  'history'  => $rows,  'total'  => $total,  'page'  => $page,  'per_page'  => $per_page,  'total_pages' => $total > 0 ? (int)ceil($total / $per_page) : 1,  ]);
}  function handle_submit_fuel_stock_in($pdo, $me, $role, $station_id) {  $input = json_decode(file_get_contents('php://input'), true);  if (!$input) {  echo json_encode(['success' => false, 'message' => 'Invalid JSON input']);  return;  }  $oversight_delivery_id = (int)($input['oversight_delivery_id'] ?? 0); // NEW: from deliveries_oversight  $delivery_id  = (int)($input['delivery_id']  ?? 0);  // LEGACY: from fuel_deliveries  $qty_received  = (float)($input['qty_received']  ?? 0);  $condition  = $input['condition']  ?? 'Good';  $remarks  = trim($input['remarks']  ?? '');  $batch_id  = trim($input['batch_id']  ?? '');  $unit_cost  = (float)($input['unit_cost']  ?? 0);  // Prioritize oversight_delivery_id (new flow from Admin processing)  if ($oversight_delivery_id > 0) {  // NEW FLOW: Fetch from deliveries_oversight  $stmt = $pdo->prepare("  SELECT  do2.id AS oversight_id,  do2.delivery_ref,  do2.supplier,  do2.product AS fuel_type,  do2.quantity AS delivery_liters,  do2.expected_quantity,  do2.actual_quantity,  do2.unit_price,  do2.batch_id AS delivery_batch_id,  do2.dr_number AS invoice_no  FROM deliveries_oversight do2  WHERE do2.id = ? AND do2.station_id = ?  AND do2.delivery_type = 'fuel'  AND do2.status IN ('Ready for Stock-In', 'Validated', 'Partial Delivery', 'Damaged Items')  ");  $stmt->execute([$oversight_delivery_id, $station_id]);  $del = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$del) {  echo json_encode(['success' => false, 'message' => 'Fuel delivery not found, not yet validated by Admin, or already stocked in.']);  return;  }  $fuel_type = $del['fuel_type'];  $qty_expected = (float)((float)$del['actual_quantity'] ?: $del['delivery_liters']);  $delivery_ref_id = $oversight_delivery_id;  $is_new_flow = true;  if (!$batch_id && !empty($del['delivery_batch_id'])) {  $batch_id = $del['delivery_batch_id'];  }  } elseif ($delivery_id > 0) {  // LEGACY FLOW: Fetch from fuel_deliveries  $stmt = $pdo->prepare("  SELECT * FROM fuel_deliveries  WHERE id = ? AND station_id = ? AND status = 'Awaiting Stock-In'  ");  $stmt->execute([$delivery_id, $station_id]);  $del = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$del) {  echo json_encode(['success' => false, 'message' => 'Pending fuel delivery not found or already stocked in.']);  return;  }  $fuel_type = $del['fuel_type'];  $qty_expected = (float)$del['delivery_liters'];  $delivery_ref_id = $delivery_id;  $is_new_flow = false;  } else {  echo json_encode(['success' => false, 'message' => 'Delivery ID is required']);  return;  }  if ($qty_received < 0) {  echo json_encode(['success' => false, 'message' => 'Quantity received cannot be negative']);  return;  }  // Resolve fuel_type_id  $fuel_type_id = null;  try {  $ftStmt = $pdo->prepare("SELECT fuel_type_id FROM fuel_inventory WHERE station_id = ? AND LOWER(TRIM(fuel_type)) = LOWER(TRIM(?)) LIMIT 1");  $ftStmt->execute([$station_id, $fuel_type]);  $ftRow = $ftStmt->fetch(PDO::FETCH_ASSOC);  if ($ftRow) $fuel_type_id = (int)$ftRow['fuel_type_id'];  } catch (Exception $e) {}  if (!$fuel_type_id) {  try {  $ftStmt2 = $pdo->prepare("SELECT id FROM fuel_types WHERE LOWER(TRIM(name)) = LOWER(TRIM(?)) LIMIT 1");  $ftStmt2->execute([$fuel_type]);  $fuel_type_id = (int)($ftStmt2->fetchColumn() ?: null);  } catch (Exception $e) {}  }  // Get level before stock-in  $level_before = 0;  try {  $lvlStmt = $pdo->prepare("SELECT COALESCE(current_level, current_stock, 0) FROM fuel_inventory WHERE station_id = ? AND LOWER(TRIM(fuel_type)) = LOWER(TRIM(?)) LIMIT 1");  $lvlStmt->execute([$station_id, $fuel_type]);  $level_before = (float)($lvlStmt->fetchColumn() ?: 0);  } catch (Exception $e) {}  // Only add to inventory if condition is Good or Excess  $qty_to_add = 0;  if (in_array($condition, ['Good', 'Excess'])) {  $qty_to_add = $qty_received;  }  // Short/Damaged: do NOT add to inventory (flag only)  $level_after  = $level_before + $qty_to_add;  $qty_variance = $qty_received - $qty_expected;  // Use provided batch_id as batch_ref if supplied, otherwise auto-generate  $batch_ref  = $batch_id ?: 'FI-SI-' . date('Ymd-His') . '-DEL' . str_pad($delivery_id, 4, '0', STR_PAD_LEFT);  $pdo->beginTransaction();  try {  // Update delivery status  if ($is_new_flow) {  // NEW FLOW: Update deliveries_oversight  $pdo->prepare("  UPDATE deliveries_oversight  SET status = 'Stock-In Complete',  updated_at = NOW()  WHERE id = ?  ")->execute([$oversight_delivery_id]);  } else {  // LEGACY FLOW: Update fuel_deliveries  $pdo->prepare("  UPDATE fuel_deliveries  SET status = 'Stock-In Complete',  notes = CONCAT(IFNULL(notes,''), ' | Stock-In Completed: ', ?)  WHERE id = ?  ")->execute([$remarks ?: 'Completed', $delivery_id]);  // If PO-based, also update deliveries_oversight status to 'Stock-In Complete'  if ($del['invoice_no']) {  try {  $pdo->prepare("  UPDATE deliveries_oversight  SET status = 'Stock-In Complete',  updated_at = NOW()  WHERE station_id = ? AND dr_number = ? AND LOWER(TRIM(product)) = LOWER(TRIM(?))  ")->execute([$station_id, $del['invoice_no'], $fuel_type]);  } catch (Exception $e) {}  }  }  // Update fuel_inventory  if ($qty_to_add > 0) {  $upd = $pdo->prepare("  UPDATE fuel_inventory  SET current_level = COALESCE(current_level, 0) + ?,  current_stock = COALESCE(current_stock, 0) + ?,  last_updated  = NOW()  WHERE station_id = ? AND LOWER(TRIM(fuel_type)) = LOWER(TRIM(?))  ");  $upd->execute([$qty_to_add, $qty_to_add, $station_id, $fuel_type]);  if ($upd->rowCount() === 0 && $fuel_type_id) {  $pdo->prepare("  INSERT INTO fuel_inventory  (station_id, fuel_type_id, fuel_type, current_level, current_stock, last_updated)  VALUES (?, ?, ?, ?, ?, NOW())  ")->execute([$station_id, $fuel_type_id, $fuel_type, $qty_to_add, $qty_to_add]);  }  // Insert into fuel_adjustments  if ($fuel_type_id) {  try {  $audit_reason = "Stock-In | Delivery #{$delivery_id} received. Liters: {$qty_received} ({$condition}). Notes: {$remarks}";  $pdo->prepare("  INSERT INTO fuel_adjustments  (station_id, fuel_type_id, adjustment_type, liters, reason, user_id, adjustment_date)  VALUES (?, ?, 'delivery', ?, ?, ?, CURDATE())  ")->execute([$station_id, $fuel_type_id, $qty_to_add, $audit_reason, $me['id']]);  } catch (Exception $ae) {  error_log("fuel_adjustments insert failed: " . $ae->getMessage());  }  }  }  // Insert into fuel_stock_in  $pdo->prepare("  INSERT INTO fuel_stock_in  (delivery_id, invoice_no, station_id, fuel_type, qty_expected, qty_received, qty_variance,  condition_flag, remarks, level_before, level_after, encoded_by, encoded_at, batch_ref, delivery_ref)  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?)  ")->execute([  $delivery_ref_id,  $del['invoice_no'] ?? '',  $station_id,  $fuel_type,  $qty_expected,  $qty_received,  $qty_variance,  $condition,  $remarks,  $level_before,  $level_after,  $me['id'],  $batch_ref,  $del['delivery_ref'] ?? ''  ]);  // ── Create / Update fuel_batches record (FIFO tracking) ───────────────  if ($fuel_type_id && in_array($condition, ['Good', 'Excess'])) {  try {  // Check if this batch_ref already exists (idempotency guard)  $existStmt = $pdo->prepare(  "SELECT id, remaining_qty FROM fuel_batches WHERE batch_number = ? AND station_id = ? LIMIT 1"  );  $existStmt->execute([$batch_ref, $station_id]);  $existBatch = $existStmt->fetch(PDO::FETCH_ASSOC);  if ($existBatch) {  // Increment remaining_qty on the existing batch  $pdo->prepare("  UPDATE fuel_batches  SET remaining_qty  = remaining_qty + ?,  quantity_received = quantity_received + ?,  updated_at  = NOW()  WHERE id = ?  ")->execute([$qty_to_add, $qty_to_add, $existBatch['id']]);  } else {  // Insert new batch record  $pdo->prepare("  INSERT INTO fuel_batches  (fuel_type_id, station_id, batch_number, delivery_id,  quantity_received, remaining_qty, unit_cost,  supplier, date_received, encoded_by, notes)  VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURDATE(), ?, ?)  ")->execute([  $fuel_type_id,  $station_id,  $batch_ref,  $delivery_ref_id,  $qty_to_add,  $qty_to_add,  $unit_cost ?: 0,  $del['supplier'] ?? null,  $me['id'],  $remarks ?: null  ]);  }  } catch (Exception $be) {  error_log('fuel_batches insert/update failed: ' . $be->getMessage());  }  }  // Audit log  $ref_desc = $is_new_flow ? "Delivery #{$oversight_delivery_id} ({$del['delivery_ref']})" : "Delivery #{$delivery_id}";  $detail = "Fuel Stock-In | {$ref_desc} | Fuel: {$fuel_type} | Received: {$qty_received} L | Batch: {$batch_ref}";  if ($remarks) $detail .= " | Note: {$remarks}";  try {  $entity_type = $is_new_flow ? 'deliveries_oversight' : 'fuel_deliveries';  $pdo->prepare("  INSERT INTO audit_logs  (user_id, log_type, action_type, action_details, entity_type, entity_id, status, ip_address, user_agent, created_at)  VALUES (?, 'fuel_management', 'Fuel Stock-In', ?, ?, ?, 'Success', ?, ?, NOW())  ")->execute([  $me['id'], $detail, $entity_type, $delivery_ref_id,  $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0',  $_SERVER['HTTP_USER_AGENT'] ?? ''  ]);  } catch (Exception $e) {}  if (function_exists('log_activity')) {  log_activity($pdo, $me['id'], 'Fuel Stock-In', $detail);  }  $pdo->commit();  echo json_encode([  'success'  => true,  'message'  => "Stock-In complete. Tank level updated for {$fuel_type}.",  'batch_ref'  => $batch_ref,  'batch_id'  => $batch_id ?: $batch_ref,  ]);  } catch (Exception $e) {  $pdo->rollBack();  throw $e;  }
}
